/** A small POST form with hidden fields and one button. */
function button(action, fields, label, primary = false) {
  const hidden = Object.entries(fields).map(([k, v]) => `<input type="hidden" name="${esc(k)}" value="${esc(v)}">`).join("");
  return `<form method="post" action="${esc(action)}">${hidden}<button${primary ? ' class="primary"' : ""}>${esc(label)}</button></form>`;
}

/* eslint-disable @typescript-eslint/no-unused-vars -- shared helpers, pasted in front of the Code nodes that use them */
/**
 * Shared by the n8n Code nodes that talk to Claude (pasted in by pack-workflows.mjs).
 * claudeRequest() builds a Messages API body; the HTTP node "… Claude" sends it with the
 * credential "Claude API (BEER)". claudeAnswer() reads the JSON answer back.
 */

const MODEL = "claude-opus-5-5";

/**
 * schema: JSON schema for structured output (strict JSON back).
 * webSearch: number of searches allowed; then the answer is asked for as a JSON block in the
 * text instead, since search results come back with citations.
 */
function claudeRequest({ system, user, schema, effort = "medium", maxTokens = 16000, webSearch = 0 }) {
  const request = {
    model: MODEL,
    max_tokens: maxTokens,
    system,
    output_config: { effort },
    // Lets the API answer with a fallback model when a request is declined.
    fallbacks: "default",
    messages: [{ role: "user", content: user }],
  };
  if (webSearch) {
    request.tools = [
      {
        type: "web_search_20260209",
        name: "web_search",
        max_uses: webSearch,
        user_location: { type: "approximate", city: "Freising", region: "Bayern", country: "DE", timezone: "Europe/Berlin" },
      },
    ];
    if (schema) {
      request.system += `\n\nAntworte am Ende ausschließlich mit einem JSON-Objekt nach diesem Schema, ohne weiteren Text:\n${JSON.stringify(schema)}`;
    }
  } else if (schema) {
    request.output_config.format = { type: "json_schema", schema };
  }
  return request;
}

/** { value } with the parsed JSON answer, or { error } when the call produced none. */
function claudeAnswer(response) {
  if (!response || response.type === "error" || response.error) {
    // After retries the HTTP node passes the failure on as { error: "…" } or { error: { message } }.
    const error = response?.error;
    const message = typeof error === "string" ? error : error?.message ?? response?.message ?? "keine Antwort";
    return { error: `Claude: ${message}` };
  }
  if (response.stop_reason === "refusal") return { error: "Claude hat abgelehnt." };
  if (response.stop_reason === "max_tokens") return { error: "Antwort abgeschnitten (max_tokens)." };
  if (response.stop_reason === "pause_turn") return { error: "Suche nicht fertig geworden – bitte erneut starten." };
  const text = (response.content ?? []).filter((block) => block.type === "text").map((block) => block.text).join("");
  for (const candidate of [text, text.match(/```(?:json)?\s*([\s\S]*?)```/)?.[1], text.slice(text.indexOf("{"), text.lastIndexOf("}") + 1)]) {
    if (!candidate) continue;
    try {
      return { value: JSON.parse(candidate), sources: webSources(response) };
    } catch {
      // try the next form
    }
  }
  return { error: "Antwort war kein gültiges JSON." };
}

/** The pages Claude's web searches returned (title and address), for reports. */
function webSources(response) {
  const seen = new Map();
  for (const block of response.content ?? []) {
    if (block.type !== "web_search_tool_result" || !Array.isArray(block.content)) continue;
    for (const hit of block.content) if (hit.url && !seen.has(hit.url)) seen.set(hit.url, hit.title ?? hit.url);
  }
  return [...seen].map(([url, title]) => ({ url, title }));
}

/** Short company facts every prompt may use; nothing beyond these may be invented. */
const BEER_FACTS = `BEER Küchenmanufaktur: Schreinerei und Küchenmanufaktur mit eigener Fertigung und Ausstellung in Wolfersdorf bei Freising (Bayern). Plant und baut Küchen und Möbel nach Maß für Kundinnen und Kunden im Raum München, Freising, Landshut und Umgebung. Arbeitet mit Geräten und Materialien unter anderem von Bora, Miele, Gaggenau, Siemens, Quooker und Fenix.`;

/* eslint-disable @typescript-eslint/no-unused-vars -- shared helpers, pasted in front of the Code nodes that use them */
/**
 * Shared by the Code nodes of "BEER Ratgeber" (pasted in after lib-common.js): turns the
 * answers of "Bestand lesen" into one object with articles, FAQ, topics, categories and
 * projects, and lists the internal pages an article may link to.
 */

function ratgeberBestand() {
  const requests = $("Bestand lesen: Auftrag").all().map((item) => item.json);
  const answers = $("Bestand lesen").all().map((item) => item.json);
  const out = { articles: [], faq: [], topics: [], categories: [], projects: [], trigger: requests[0]?.trigger ?? {} };
  answers.forEach((answer, i) => {
    const kind = requests[i]?.kind;
    if (kind && Array.isArray(answer?.data)) out[kind].push(...answer.data);
  });
  return out;
}

/** Internal pages Claude may link to, as "path – title" lines. */
function ratgeberLinks(bestand) {
  const fixed = [
    ["/kueche-planen", "Küche planen"],
    ["/beratung", "Beratung"],
    ["/ausstellung", "Ausstellung in Wolfersdorf"],
    ["/projekte", "Alle Projekte"],
    ["/kontakt", "Kontakt"],
  ];
  return [
    ...fixed,
    ...bestand.topics.map((t) => [`/kuechen/${t.cluster}/${t.slug}`, t.name]),
    ...bestand.articles.map((a) => [`/${a.category?.slug === "presse" ? "presse" : "ratgeber"}/${a.slug}`, a.title]),
  ].map(([path, title]) => `${path} – ${title}`);
}

const RATGEBER_CATEGORIES = ["kosten", "planung", "geraete", "material"];

/**
 * n8n Code node "Seite" (workflow "BEER Ratgeber"): topic ideas and written drafts.
 */

const BASE = "/webhook/beer-ratgeber";
const store = $getWorkflowStaticData("global");
const query = $input.first()?.json?.query ?? {};
const topics = Object.values(store.topics ?? {}).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
const by = (status) => topics.filter((t) => t.status === status);

const label = { kosten: "Kosten", planung: "Planung", geraete: "Geräte", material: "Material" };
const ideaCard = (t) => `<section class="card"><b>${esc(t.title)}</b> <span class="small">· ${esc(label[t.category] ?? t.category)}</span>
<div>${esc(t.question)}</div>
<div class="small" style="margin-top:6px">${esc(t.why)}<br>BEER-Beitrag: ${esc(t.angle)}</div>
${t.projects?.length ? `<div class="small">Projekte: ${t.projects.map((s) => `<a href="${esc(`${SITE}/projekte/${s}`)}" target="_blank">${esc(s)}</a>`).join(", ")}</div>` : ""}
${t.sources?.length ? `<div class="small">Belege: ${t.sources.map((u, i) => `<a href="${esc(u)}" target="_blank" rel="noopener">Quelle ${i + 1}</a>`).join(" · ")}</div>` : ""}
${t.error ? `<p class="fehler">${esc(t.error)}</p>` : ""}
<div class="actions">${button(`${BASE}/aktion`, { topicId: t.id, aktion: "schreiben" }, "Artikel schreiben lassen", true)}${button(`${BASE}/aktion`, { topicId: t.id, aktion: "verwerfen" }, "Verwerfen")}</div></section>`;

const draftRow = (t) => `<tr><td><a href="${esc(adminUrl("articles", t.documentId))}" target="_blank">${esc(t.draft?.title ?? t.title)}</a>
<div class="small">${esc(when(t.writtenAt))} · ${t.draft?.words ?? "?"} Wörter · /ratgeber/${esc(t.draft?.slug ?? "")}</div></td>
<td>${t.error ? `<div class="fehler">${esc(t.error)}</div>` : ""}${t.draft?.note ? `<div>${esc(t.draft.note)}</div>` : ""}
${t.draft?.checks?.length ? `<div class="hinweis">Bitte prüfen:</div><ul>${t.draft.checks.map((c) => `<li>${esc(c)}</li>`).join("")}</ul>` : ""}
${t.draft?.removedLinks?.length ? `<div class="small">Entfernte Links (nicht erlaubt): ${t.draft.removedLinks.map(esc).join(", ")}</div>` : ""}</td></tr>`;

const notice = query.gestartet
  ? "Läuft – Themen mit Web-Recherche dauern etwa zwei Minuten, ein Artikel etwa drei. Seite danach neu laden."
  : "";

const html = page(
  "Ratgeber",
  "Ratgeber",
  `<p class="small">Claude schlägt Themen vor, die Menschen vor dem Küchenkauf wirklich suchen und die die BEER aus eigener Erfahrung beantworten kann. Ein Klick lässt den Artikel schreiben – aus den FAQ-Antworten und den passenden Projekten, mit Links auf die eigenen Seiten. Er landet als <b>Entwurf</b> in Strapi; Stellen mit „[prüfen: …]“ brauchen eine Angabe der BEER. Etwa zwei Artikel im Monat genügen; Qualität zählt mehr als Menge.</p>
<section class="card"><div class="actions">${button(`${BASE}/themen`, {}, "Neue Themen vorschlagen lassen", true)}</div>
<form method="post" action="${BASE}/aktion" style="margin-top:12px"><input type="hidden" name="aktion" value="eigenes">
<input name="title" placeholder="Eigenes Thema, z. B. Arbeitsplatten im Vergleich" size="44" required>
<select name="category">${Object.entries(label).map(([v, l]) => `<option value="${v}">${l}</option>`).join("")}</select>
<button>Thema hinzufügen</button></form></section>
${by("schreibt").length ? `<h2>Wird geschrieben</h2><ul>${by("schreibt").map((t) => `<li>${esc(t.title)} <span class="small">seit ${esc(when(t.startedAt))}</span></li>`).join("")}</ul>` : ""}
<h2>Themen (${by("offen").length})</h2>${by("offen").map(ideaCard).join("") || `<p class="small">Noch keine Themen – oben vorschlagen lassen.</p>`}
${by("entwurf").length ? `<h2>Entwürfe in Strapi</h2><table>${by("entwurf").map(draftRow).join("")}</table>` : ""}
${(store.log ?? []).length ? `<details><summary class="small">Verlauf</summary><ul class="small">${store.log.slice(0, 15).map((l) => `<li>${esc(when(l.at))}: ${esc(l.text)}</li>`).join("")}</ul></details>` : ""}`,
  notice,
);

return [{ json: { html } }];

